{"function":"async () => {
// inspect focus indicator for each tabbable via programmatic focus
const out=[];
const els=[...document.querySelectorAll('a[href],button,input,textarea,[tabindex]')].filter(e=>e.tabIndex>=0&&!e.disabled&&e.getClientRects().length);
for(const e of els){e.focus(); const c=getComputedStyle(e); out.push((e.id||e.className.slice(0,25)||e.tagName)+' | '+c.outlineStyle+' '+c.outlineWidth+' '+c.outlineColor+' | sh:'+(c.boxShadow!=='none'?'y':'n'));}
return out;}"}

